test('a failed refresh keeps the orders and the next good one clears the message', async () => {
  let fail = false
  const store = createStore({
    listOrders: async () => {
      if (fail) throw new Error('HTTP 503')
      return ORDERS
    },
  })
  await store.load('')
  fail = true
  await store.refresh()
  assert.equal(store.state.error, 'Could not refresh orders.')
  assert.equal(store.state.orders.length, 2)
  fail = false
  await store.refresh()
  assert.equal(store.state.error, null)
})

test('subscribers hear about each change'

